Input: {"question": "When was Marina High School established?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0351-559a2e86d466:d00", "start": 0, "end": 193, "text": "Marina High School (Huntington Beach, California) Marina High School is a public high school located in the northwest corner of Huntington Beach, California which first began operating in 1963."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0351-559a2e86d466:d00", "start": 194, "end": 308, "text": "Marina is part of the Huntington Beach Union High School District, which includes several other area high schools."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0351-559a2e86d466:d00", "start": 309, "end": 395, "text": "The school is located on Springdale Street between Edinger Avenue and McFadden Avenue."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0351-559a2e86d466:d00", "start": 396, "end": 510, "text": "In 2009, the school was named a California Distinguished School, the highest honor given to schools in California."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0351-559a2e86d466:d00", "start": 511, "end": 623, "text": "Marina's athletic teams are known as the Vikings and their school colors are Navy Blue, Columbia Blue, and Gold."}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0351-559a2e86d466:d00", "start": 624, "end": 639, "text": "They compete in"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0351-559a2e86d466:d01", "start": 0, "end": 265, "text": "Search Help Frequently Asked Questions Home Resources School Directory Marina High California School Directory Marina High New Search County Orange District Huntington Beach Union High School Marina High CDS Code 30 66548 3034410 School Address 15871 Springdale St."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0351-559a2e86d466:d01", "start": 266, "end": 372, "text": "Huntington Beach, CA 92649-1727 Google Map Link opens new browser tab Mailing Address 15871 Springdale St."}, "D